DELETE FROM Language_en_US WHERE Tag='TXT_KEY_CWC_GUIDE_THESHATTEREDEMPIRE' OR Tag GLOB 'TXT_KEY_CWC_GUIDE_THESHATTEREDEMPIRE_*';
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC_GUIDE_THESHATTEREDEMPIRE_CIV_HEADING_1','Playstyle and victory plan');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC_GUIDE_THESHATTEREDEMPIRE_CIV_TEXT_1','Shattered Empire[NEWLINE]A strong initial footprint constrained by provincial politics[NEWLINE]Domination or Science after administrative consolidation[NEWLINE][NEWLINE]Use the starting imperial footprint to establish a lead while preventing Authority and provincial Loyalty from collapsing. Three early settlements are an opportunity to build a connected state, not an exemption from maintenance and garrison costs.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC_GUIDE_THESHATTEREDEMPIRE_CIV_HEADING_2','Opening priorities');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC_GUIDE_THESHATTEREDEMPIRE_CIV_TEXT_2','Inspect whether the provincial entitlements produced cities or fallback Settlers. Connect and defend the provinces, improve food, and manage the treasury. Keep the starting Authority advantage rather than spending it on avoidable losses.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC_GUIDE_THESHATTEREDEMPIRE_CIV_HEADING_3','Develop the engine');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC_GUIDE_THESHATTEREDEMPIRE_CIV_TEXT_3','Read each Governor''s actual factors and demands. Build Palaces and viable connections, match garrisons to vulnerable provinces, and expand within the administration you can sustain. High Ambition is not automatically bad when Loyalty is healthy.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC_GUIDE_THESHATTEREDEMPIRE_CIV_HEADING_4','Convert the advantage');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC_GUIDE_THESHATTEREDEMPIRE_CIV_TEXT_4','Use loyal provinces to support research or a concentrated campaign. During civil war, choose suppression or negotiation according to military and political resources; diplomatic reunification can restore the empire but does not promise the same Authority reward as military success.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC_GUIDE_THESHATTEREDEMPIRE_CIV_HEADING_5','Strengths');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC_GUIDE_THESHATTEREDEMPIRE_CIV_TEXT_5','- Starting provincial entitlements create early geographic and economic options.[NEWLINE]- Governor personalities can specialize local output.[NEWLINE]- Imperial management offers both military and negotiated recovery routes.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC_GUIDE_THESHATTEREDEMPIRE_CIV_HEADING_6','Weaknesses and costs');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC_GUIDE_THESHATTEREDEMPIRE_CIV_TEXT_6','- Provinces impose maintenance and loyalty-management costs.[NEWLINE]- City and capital losses damage Authority.[NEWLINE]- Overextension, long wars and neglected demands can turn an early lead into fragmentation.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC_GUIDE_THESHATTEREDEMPIRE_CIV_HEADING_7','How to play against this civilization');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC_GUIDE_THESHATTEREDEMPIRE_CIV_TEXT_7','- Target exposed provinces and connections instead of only the main imperial stack.[NEWLINE]- Force extended commitments when Loyalty and administration are under strain.[NEWLINE]- Exploit a real succession or civil-war weakness rather than assuming three starting cities imply endless early strength.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC_GUIDE_THESHATTEREDEMPIRE_CIV_HEADING_8','Common mistakes');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC_GUIDE_THESHATTEREDEMPIRE_CIV_TEXT_8','- Leaving a newly created province without improvements, a connection or protection.[NEWLINE]- Treating a gifted fallback Settler as an obligation to found an indefensible city immediately.[NEWLINE]- Expecting negotiated-only reunification to award the full military Authority bonus.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC_GUIDE_THESHATTEREDEMPIRE_CIV_HEADING_9','Matchup examples - conditional analysis');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC_GUIDE_THESHATTEREDEMPIRE_CIV_TEXT_9','Named custom-civilization matchups are conditional mechanical analysis, not tested win rates. All custom civs are human-only and multiplayer is unsupported; these comparisons are for theorycraft or explicitly configured scenarios, not ordinary random AI opponents. General counterplay applies to normal single-player games.[NEWLINE][NEWLINE]FAVOURABLE OPPORTUNITIES[NEWLINE][NEWLINE]Luna Network: The initial imperial footprint can contest sites before Luna finishes converting cheap settlement into a defended network.[NEWLINE][NEWLINE]The Republic of First Drafts: An early organized frontier can pressure Marginalia before a broad institutional economy has matured.[NEWLINE][NEWLINE]THREATS TO RESPECT[NEWLINE][NEWLINE]The Urgal: A coordinated attack against exposed provinces can produce Authority losses before reinforcements arrive.[NEWLINE][NEWLINE]The Filthy Realm: Sustained economic pressure makes the treasury, demands and provincial stability harder to support.');
