INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC_GUIDE_THESHATTEREDEMPIRE_BACKGROUND','Use the starting imperial footprint to establish a lead while preventing Authority and provincial Loyalty from collapsing. Three early settlements are an opportunity to build a connected state, not an exemption from maintenance and garrison costs.');
