INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC_GUIDE_THESHATTEREDEMPIRE_LEADER_BACKGROUND','Use the starting imperial footprint to establish a lead while preventing Authority and provincial Loyalty from collapsing. Three early settlements are an opportunity to build a connected state, not an exemption from maintenance and garrison costs.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) SELECT 'TXT_KEY_CWC_GUIDE_THESHATTEREDEMPIRE_LEADER_BACKGROUND',Text FROM Language_en_US WHERE Tag='TXT_KEY_IMPERIAL_LEADER_PEDIA';
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC_GUIDE_THESHATTEREDEMPIRE_STRATEGY','Use the starting imperial footprint to establish a lead while preventing Authority and provincial Loyalty from collapsing. Three early settlements are an opportunity to build a connected state, not an exemption from maintenance and garrison costs.[NEWLINE][NEWLINE]Inspect whether the provincial entitlements produced cities or fallback Settlers. Connect and defend the provinces, improve food, and manage the treasury. Keep the starting Authority advantage rather than spending it on avoidable losses.[NEWLINE][NEWLINE]Read each Governor''s actual factors and demands. Build Palaces and viable connections, match garrisons to vulnerable provinces, and expand within the administration you can sustain. High Ambition is not automatically bad when Loyalty is healthy.[NEWLINE][NEWLINE]Use loyal provinces to support research or a concentrated campaign. During civil war, choose suppression or negotiation according to military and political resources; diplomatic reunification can restore the empire but does not promise the same Authority reward as military success.');
