INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC_GUIDE_THESHATTEREDEMPIRE_LEADER_HEADING_2','Priorities and decisions');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC_GUIDE_THESHATTEREDEMPIRE_LEADER_TEXT_2','Inspect whether the provincial entitlements produced cities or fallback Settlers. Connect and defend the provinces, improve food, and manage the treasury. Keep the starting Authority advantage rather than spending it on avoidable losses.[NEWLINE][NEWLINE]Read each Governor''s actual factors and demands. Build Palaces and viable connections, match garrisons to vulnerable provinces, and expand within the administration you can sustain. High Ambition is not automatically bad when Loyalty is healthy.[NEWLINE][NEWLINE]Use loyal provinces to support research or a concentrated campaign. During civil war, choose suppression or negotiation according to military and political resources; diplomatic reunification can restore the empire but does not promise the same Authority reward as military success.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC_GUIDE_THESHATTEREDEMPIRE_LEADER_HEADING_3','Matchup examples - conditional analysis');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC_GUIDE_THESHATTEREDEMPIRE_LEADER_TEXT_3','Named custom-civilization matchups are conditional mechanical analysis, not tested win rates. All custom civs are human-only and multiplayer is unsupported; these comparisons are for theorycraft or explicitly configured scenarios, not ordinary random AI opponents. General counterplay applies to normal single-player games.[NEWLINE][NEWLINE]FAVOURABLE OPPORTUNITIES[NEWLINE][NEWLINE]Luna Network: The initial imperial footprint can contest sites before Luna finishes converting cheap settlement into a defended network.[NEWLINE][NEWLINE]The Republic of First Drafts: An early organized frontier can pressure Marginalia before a broad institutional economy has matured.[NEWLINE][NEWLINE]THREATS TO RESPECT[NEWLINE][NEWLINE]The Urgal: A coordinated attack against exposed provinces can produce Authority losses before reinforcements arrive.[NEWLINE][NEWLINE]The Filthy Realm: Sustained economic pressure makes the treasury, demands and provincial stability harder to support.');
